/ {
    // This overlay defines a GNSS device node with the label 'gnns'.
    // The original error "undefined node label 'gnns'" indicates that
    // an alias or another part of the DeviceTree was referencing '&gnns'
    // but no node with that label was defined.
    // This fix provides a generic UART-based GNSS node.
    // You may need to adjust the 'compatible' string, add 'uart' phandle,
    // 'baud-rate', or other properties based on your specific GNSS module
    // and how it's connected to your board.
    gnns: gnss {
        compatible = "zephyr,gnss-uart"; // Example: generic compatible for UART-based GNSS
        status = "okay";
        label = "GNSS_0"; // A human-readable label for the device
        // Example properties (uncomment and adjust as needed):
        // uart = <&uart0>; // Phandle to the UART peripheral it's connected to
        // baud-rate = <9600>;
        // tx-pin = <&gpio0 0 GPIO_PULL_UP>; // Example GPIO for TX
        // rx-pin = <&gpio0 1 GPIO_PULL_UP>; // Example GPIO for RX
    };
};
